SELECT org, CASE WHEN same_n > 0 THEN 1 ELSE 0 END AS buyer_same_notice, CASE WHEN other_n > 0 THEN 1 ELSE 0 END AS buyer_other_notice, count(*) AS pairs FROM (SELECT q.org AS org, q.tid AS tid, q.nid AS nid, sum(CASE WHEN b.mention_notice_id = q.nid THEN 1 ELSE 0 END) AS same_n, sum(CASE WHEN b.mention_notice_id IS NOT NULL AND b.mention_notice_id <> q.nid THEN 1 ELSE 0 END) AS other_n FROM (SELECT DISTINCT 3975457 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 3975457 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid UNION ALL SELECT q.org AS org, q.tid AS tid, q.nid AS nid, sum(CASE WHEN b.mention_notice_id = q.nid THEN 1 ELSE 0 END) AS same_n, sum(CASE WHEN b.mention_notice_id IS NOT NULL AND b.mention_notice_id <> q.nid THEN 1 ELSE 0 END) AS other_n FROM (SELECT DISTINCT 1244992 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1244992 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid UNION ALL SELECT q.org AS org, q.tid AS tid, q.nid AS nid, sum(CASE WHEN b.mention_notice_id = q.nid THEN 1 ELSE 0 END) AS same_n, sum(CASE WHEN b.mention_notice_id IS NOT NULL AND b.mention_notice_id <> q.nid THEN 1 ELSE 0 END) AS other_n FROM (SELECT DISTINCT 1181455 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1181455 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid UNION ALL SELECT q.org AS org, q.tid AS tid, q.nid AS nid, sum(CASE WHEN b.mention_notice_id = q.nid THEN 1 ELSE 0 END) AS same_n, sum(CASE WHEN b.mention_notice_id IS NOT NULL AND b.mention_notice_id <> q.nid THEN 1 ELSE 0 END) AS other_n FROM (SELECT DISTINCT 1166638 AS org, p.tender_id AS tid, p.seq AS sq, p.mention_notice_id AS nid FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1166638 AND p.seq = t.current_seq LIMIT 200) q LEFT JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq AND b.role IN ('Procedure-Buyer', 'buyer') GROUP BY q.org, q.tid, q.nid) agg GROUP BY org, buyer_same_notice, buyer_other_notice ORDER BY org
